def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    colors = {v for row in grid for v in row if v != 0}
    for color in colors:
        for ar in range(h):
            for ac in range(w):
                if grid[ar][ac] != color:
                    continue
                for step in (-1, 1):
                    r = ar + step
                    radius = 1
                    while 0 <= r < h and 0 <= ac-radius and ac+radius < w:
                        if grid[r][ac-radius] != color or grid[r][ac+radius] != color:
                            break
                        for c in range(ac-radius+1, ac+radius):
                            if grid[r][c] == 0:
                                out[r][c] = 2
                        r += step
                        radius += 1
    return out
